CREATE TABLE IF NOT EXISTS records(kind TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(kind,id));
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_clock(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT OR IGNORE INTO state_clock VALUES(1,1);
CREATE TABLE IF NOT EXISTS access(meeting_id TEXT PRIMARY KEY,generation INTEGER NOT NULL,active INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,meeting_id TEXT NOT NULL,specialty TEXT NOT NULL,generation INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,role TEXT NOT NULL,status TEXT NOT NULL,meeting_id TEXT,specialty TEXT,generation INTEGER,expires INTEGER NOT NULL,label TEXT NOT NULL,code TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_meeting ON sessions(meeting_id,status);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS write_guard(id INTEGER PRIMARY KEY CHECK(id=1),ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,time INTEGER NOT NULL,action TEXT NOT NULL,meeting_id TEXT,label TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS asset_chunks(id TEXT NOT NULL,part INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(id,part));
